190	export interface MatrixCellStyleOption {
191	    // [NOTE - padding]:
192	    //  - Consider the option for the space between cell boundary to text, percentage value for
193	    //    `label.width/height` is not supported, because it is not ideal - the padding would vary
194	    //    with the cell size, making the layout inconsistent.
195	    //  - The inner text padding uses `lable.style.padding`.
196	    //    The text truncation rect is obtained by cell rect minus by padding.
197	    //  - The inner series / other coord sys padding is not supported, to avoid necessary complexity.
198	    //    Consider some series, such as heatmap, prefer no padding.
199	    label?: LabelOption;
200	    itemStyle?: ItemStyleOption;
201	    cursor?: string;
202	    // By default, auto decide whether to be silent, considering tooltip.
203	    silent?: boolean | NullUndefined;
204	    // Used when style conflict - especially for thick border style.
205	    z2?: number;
206	}
